CREATE TABLE `LIBRARY_CODE` (
  `ID` int(11) NOT NULL default '0',
  `GENRE_ID` int(11) default NULL,
  `CALL_LETTERS` varchar(3) collate utf8_unicode_ci default NULL,
  `CALL_NUMBERS` int(11) default NULL,
  `ARTIST_ID` int(11) default NULL,
  `TIME_LAST_MODIFIED` bigint(20) default NULL,
  `TIME_CREATED` bigint(20) default NULL,
  `PRESENTATION_NAME` varchar(100) collate utf8_unicode_ci default NULL,
  `ALPHABETICAL_NAME` varchar(100) collate utf8_unicode_ci default NULL,
  PRIMARY KEY  (`ID`),
  KEY `artistName` (`PRESENTATION_NAME`),
  KEY `callLetters` (`CALL_LETTERS`),
  KEY `libCodeInfo` (`GENRE_ID`,`CALL_LETTERS`,`CALL_NUMBERS`),
  KEY `alphaName` (`ALPHABETICAL_NAME`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

