DROP TABLE IF EXISTS `CHANGE_LOG`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `CHANGE_LOG` (
  `ID` int(11) NOT NULL,
  `BATCH_ID` varchar(36) NOT NULL,
  `TABLE_NAME` varchar(50) NOT NULL,
  `ROW_ID` int(11) NOT NULL,
  `ACTION` varchar(10) NOT NULL,
  `BEFORE_STATE` text default NULL,
  `AFTER_STATE` text default NULL,
  `RADIO_SHOW_ID` int(11) default NULL,
  `PERFORMED_AT` bigint(20) NOT NULL,
  `UNDONE` int(1) NOT NULL default '0',
  PRIMARY KEY  (`ID`),
  KEY `IDX_CHANGE_LOG_BATCH` (`BATCH_ID`),
  KEY `IDX_CHANGE_LOG_SHOW` (`RADIO_SHOW_ID`,`PERFORMED_AT`),
  KEY `IDX_CHANGE_LOG_TABLE` (`TABLE_NAME`,`PERFORMED_AT`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
